CREATE PROCEDURE [MoveData].[usp_MigrateExtendInsurance]     @IdaraId bigint,     @RollbackAfterTest bit = 1 AS BEGIN     SET NOCOUNT ON;     /* Normalize migration administration: preserve a valid supplied value, otherwise use Idara 1. */     IF NOT EXISTS (SELECT 1 FROM dbo.Idara WHERE idaraID = 1)         THROW 57990, N'Default migration Idara 1 does not exist.', 1;     IF @IdaraId IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Idara WHERE idaraID = @IdaraId)         SET @IdaraId = 1;     SET XACT_ABORT ON;      IF NOT EXISTS (SELECT 1 FROM [dbo].[Idara] WHERE [idaraID] = @IdaraId)         THROW 55500, N'The supplied IdaraId does not exist in DATACORE.dbo.Idara.', 1;     IF NOT EXISTS (SELECT 1 FROM [Housing].[BuildingAction])         THROW 55501, N'Run MoveData.usp_MigrateBuildingActions before migrating extend insurance.', 1;      DECLARE @ExpectedInsurance bigint = 0,             @InsertedInsurance bigint = 0;      ;WITH LastAction AS     (         SELECT             targetAction.*,             ROW_NUMBER() OVER             (                 PARTITION BY targetAction.[generalNo_FK]                 ORDER BY ISNULL(targetAction.[buildingActionDate], targetAction.[entryDate]) DESC,                          targetAction.[buildingActionID] DESC             ) AS rowNumber         FROM [Housing].[BuildingAction] targetAction
        JOIN Housing.ResidentInfo eligibleResident
          ON eligibleResident.residentInfoID=targetAction.residentInfoID_FK
         AND eligibleResident.residentInfoActive=1
        WHERE targetAction.[generalNo_FK] IS NOT NULL           AND ISNULL(targetAction.[buildingActionActive], 1) = 1     )     SELECT @ExpectedInsurance = COUNT_BIG(*)     FROM LastAction     WHERE rowNumber = 1       AND [buildingActionTypeID_FK] = 24       AND [buildingActionExtraType1] = 2;      BEGIN TRY         BEGIN TRANSACTION;          ;WITH LastAction AS         (             SELECT                 targetAction.*,                 ROW_NUMBER() OVER                 (                     PARTITION BY targetAction.[generalNo_FK]                     ORDER BY ISNULL(targetAction.[buildingActionDate], targetAction.[entryDate]) DESC,                              targetAction.[buildingActionID] DESC                 ) AS rowNumber             FROM [Housing].[BuildingAction] targetAction
        JOIN Housing.ResidentInfo eligibleResident
          ON eligibleResident.residentInfoID=targetAction.residentInfoID_FK
         AND eligibleResident.residentInfoActive=1
        WHERE targetAction.[generalNo_FK] IS NOT NULL               AND ISNULL(targetAction.[buildingActionActive], 1) = 1         )         INSERT INTO [Housing].[ExtendInsurance]         (             [buildingActionID_FK], [residentInfoID_FK], [buildingDetailsID_FK],             [buildingDetailsNo], [InsuranceAmount], [Remaining],             [InsuranceAmountWithRemaining], [ExtendInsuranceNo],             [ExtendInsuranceDate], [ExtendInsuranceType], [ExtendInsuranceNote],             [ExtendInsuranceActive], [ExtendInsuranceApproved], [IdaraId_FK],             [entryDate], [entryData], [hostName]         )         SELECT             sourceAction.[buildingActionID],             sourceAction.[residentInfoID_FK],             sourceAction.[buildingDetailsID_FK],             sourceAction.[buildingDetailsNo],             sourceAction.[buildingActionExtraFloat1],             0,             sourceAction.[buildingActionExtraFloat1],             sourceAction.[buildingActionDecisionNo],             sourceAction.[entryDate],             1,             sourceAction.[buildingActionNote],             1,             0,             @IdaraId,             sourceAction.[entryDate],             sourceAction.[entryData],             sourceAction.[hostName]         FROM LastAction sourceAction         WHERE sourceAction.rowNumber = 1           AND sourceAction.[buildingActionTypeID_FK] = 24           AND sourceAction.[buildingActionExtraType1] = 2           AND NOT EXISTS           (               SELECT 1               FROM [Housing].[ExtendInsurance] targetInsurance               WHERE targetInsurance.[buildingActionID_FK] = sourceAction.[buildingActionID]           );          SET @InsertedInsurance = @@ROWCOUNT;          SELECT             @RollbackAfterTest [RollbackAfterTest],             @ExpectedInsurance [ExpectedExtendInsurance],             (SELECT COUNT_BIG(*) FROM [Housing].[ExtendInsurance] WHERE [IdaraId_FK] = @IdaraId) [AvailableExtendInsurance],             @InsertedInsurance [ExtendInsuranceInserted],             (SELECT SUM([InsuranceAmount]) FROM [Housing].[ExtendInsurance] WHERE [IdaraId_FK] = @IdaraId) [InsuranceAmountTotal],             (SELECT SUM([Remaining]) FROM [Housing].[ExtendInsurance] WHERE [IdaraId_FK] = @IdaraId) [RemainingTotal],             (SELECT SUM([InsuranceAmountWithRemaining]) FROM [Housing].[ExtendInsurance] WHERE [IdaraId_FK] = @IdaraId) [InsuranceAmountWithRemainingTotal];          IF @RollbackAfterTest = 1 ROLLBACK TRANSACTION; ELSE COMMIT TRANSACTION;     END TRY     BEGIN CATCH         IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;         THROW;     END CATCH; END;